# C:Users\u000BladeOneDriveDocumentosGitHubStrategicFlow\backendsrcmodulescrmotifications.pyimport asyncioimport loggingfrom datetime import datetime, timedeltafrom typing import Optionalfrom aiohttp import ClientSessionimport aiojobslogger = logging.getLogger("crm_notifications")# ============================================# 📧 SERVIÇO DE NOTIFICAÇÃO (Email automatizado)# ============================================# 👉 AUTOMAÇÃO 1: Disparar email 7 dias após fechamento de contrato# 👉 AUTOMAÇÃO 2: Notificar when oportunidade fica "stagnada" (30+ dias no mesmo estágio)# 👉 AUTOMAÇÃO 3: Notificar next_action quando data chegar (task reminder)class NotificationService:    """Serviço de notificação e automação do CRM"""        def __init__(self, email_api_url: str = "http://localhost:8002/api/email/send"):        self.email_api_url = email_api_url        self.scheduler = None        async def start_scheduler(self):        """        Iniciar scheduler de notificações automáticas        👉 CHECK EVERY HOUR: Verificar oportunidades confluentes, next_actions, etc        """        self.scheduler = await aiojobs.create_scheduler()        logger.info("✅ Scheduler de notificações iniciado")                # Job que roda a cada 1 hora        await self.scheduler.spawn(self._hourly_check)        async def _hourly_check(self):        """        Check horário de notificações automáticas        👉 AUTOMAÇÃO: Executar a cada 1 hora        """        try:            # 1. Check oportunidades fechadas (enviar email agendamento)            await self._check_closed_opportunities()                        # 2. Check próximos actions (reminder)            await self._check_next_actions()                        # 3. Check oportunidades stagnadas            await self._check_stagnated_opportunities()                    except Exception as e:            logger.error(f"❌ Erro check horário: {e}")                # Re-espaçar job para 1 hora        await asyncio.sleep(3600)        await self._hourly_check()        async def _check_closed_opportunities(self):        """        Check oportunidades fechadas nos últimos 7 dias        👉 AUTOMAÇÃO: Enviar email para agendar primeira reunião        👉 SELECT: SELECT * FROM opportunities WHERE stage = 'fechado_positivo' AND closed_date > NOW() - 7 days        """        from core.database import get_db        db = await get_db()                # 👉 SELECT NO DATABASE        closed_opps = await db.fetch(            """            SELECT o.*, c.razao_social, c.email             FROM opportunities o            JOIN clients c ON o.client_id = c.id            WHERE o.stage = 'fechado_positivo'             AND o.closed_date >= CURRENT_TIMESTAMP - INTERVAL '7 days'            AND o.closed_date < CURRENT_TIMESTAMP            AND o.tenant_id = $1            """,            "default-tenant"        )                for opp in closed_opps:            # 👉 DISPARAR EMAIL (Chamar API de email)            await self._send_email(                to=opp["email"],                subject=f"🎉 Contrato Fechado: {opp['title']}",                body=self._build_closed_email_body(opp)            )                        logger.info(f"✅ Email disparado: Contrato fechado {opp['title']} -> {opp['email']}")        async def _send_email(self, to: str, subject: str, body: str):        """        Disparar email via API externa        👉 POST: POST {email_api_url} {to, subject, body}        """        try:            async with ClientSession() as session:                async with session.post(                    self.email_api_url,                    json={"to": to, "subject": subject, "body": body}                ) as resp:                    if resp.status == 200:                        logger.info(f"✅ Email enviado: {to}")                    else:                        logger.error(f"❌ Erro enviar email: {resp.status}")        except Exception as e:            logger.error(f"❌ Erro chamar API email: {e}")        def _build_closed_email_body(self, opp: dict) -> str:        """        Construir corpo de email para contrato fechado        👉 AUTOMAÇÃO: Email template        """        return f"""        Olá {opp['razao_social']},                🎉 Parabéns! Seu contrato foi fechado com sucesso!                Projeto: {opp['title']}        Valor: R$ {opp['value_closed']}                Vamos agendar nossa primeira reunião de alinhamento?        Por favor, confirme sua disponibilidade para os próximos 7 dias.                Atenciosamente,        Vlademir Oliveira        Consultor Warehousing & Processos        """        async def _check_next_actions(self):        """        Check next_actions que vencem hoje ou amanhã        👉 AUTOMAÇÃO: Reminder de task futura        👉 SELECT: SELECT * FROM interactions WHERE next_action_date = TODAY OR TOMORROW        """        from core.database import get_db        db = await get_db()                today = datetime.now()        tomorrow = today + timedelta(days=1)                # 👉 SELECT NO DATABASE        actions = await db.fetch(            """            SELECT * FROM interactions             WHERE next_action_date >= CURRENT_DATE             AND next_action_date <= CURRENT_DATE + INTERVAL '1 day'            AND next_action IS NOT NULL            AND tenant_id = $1            """,            "default-tenant"        )                for action in actions:            # 👉 DISPARAR EMAIL (Reminder)            await self._send_email(                to="vlademir@strategicflow.com",  # Email do consultor                subject=f"⏰ Reminder: {action['next_action']}",                body=f"""                Task pendente: {action['next_action']}                Data: {action['next_action_date']}                Interação: {action['title']}                """            )                        logger.info(f"✅ Reminder disparado: {action['next_action']}")        async def _check_stagnated_opportunities(self):        """        Check oportunidades stagnadas (30+ dias no mesmo estágio)        👉 AUTOMAÇÃO: Alerta de oportunidade "esquecida"        👉 SELECT: SELECT * FROM opportunities WHERE updated_at < NOW() - 30 days AND stage != 'fechado_*'        """        from core.database import get_db        db = await get_db()                # 👉 SELECT NO DATABASE        stagnated = await db.fetch(            """            SELECT o.*, c.razao_social             FROM opportunities o            JOIN clients c ON o.client_id = c.id            WHERE o.updated_at < CURRENT_TIMESTAMP - INTERVAL '30 days'            AND o.stage NOT IN ('fechado_positivo', 'fechado_negativo')            AND o.tenant_id = $1            """,            "default-tenant"        )                for opp in stagnated:            # 👉 DISPARAR EMAIL (Alerta)            await self._send_email(                to="vlademir@strategicflow.com",                subject=f"⚠️ Oportunidade Stagnada: {opp['title']}",                body=f"""                Oportunidade está no estágio '{opp['stage']}' há 30+ dias!                Cliente: {opp['razao_social']}                Valor: R$ {opp['value_expected']}                                Ação sugerida: Retomar contato com o cliente                """            )                        logger.info(f"✅ Alerta disparado: Oportunidade stagnada {opp['title']}")        async def send_welcome_email(self, client_email: str, client_name: str):        """        Enviar email de welcome ao novo cliente        👉 AUTOMAÇÃO: Email de boas-vindas        """        await self._send_email(            to=client_email,            subject="👋 Bem-vindo ao Strategic Flow!",            body=f"""            Olá {client_name},                        Bem-vindo ao Strategic Flow - Consultoria em Warehousing & Processos!                        Estamos thrilled para trabalhar com você.                        Atenciosamente,            Vlademir Oliveira            """        )# ============================================# 📅 AUTOMAÇÃO: Agendamento de Reunião (Calendar API)# ============================================# 👉 AUTOMAÇÃO: Quando criar interação type='reuniao', criar evento no Google Calendarclass CalendarService:    """Serviço de integração com Google Calendar"""        def __init__(self, calendar_api_key: str, calendar_credentials: str):        self.calendar_api_key = calendar_api_key        self.calendar_credentials = calendar_credentials        async def create_meeting_event(        self,         title: str,         description: str,         start_time: datetime,         end_time: datetime,        attendees: list[str]    ):        """        Criar evento de reunião no Google Calendar        👉 POST: POST https://www.googleapis.com/calendar/v3/calendars/primary/events {event}        """        import googleapiclient.discovery        from googleapiclient.discovery import build                # 👉 AUTENTICAR Google Calendar        credentials = load_credentials(self.calendar_credentials)        calendar = build('calendar', 'v3', credentials=credentials)                event = {            'summary': title,            'description': description,            'start': {                'dateTime': start_time.isoformat(),                'timeZone': 'America/Sao_Paulo'            },            'end': {                'dateTime': end_time.isoformat(),                'timeZone': 'America/Sao_Paulo'            },            'attendees': [{'email': a} for a in attendees],            'reminders': {                'useDefault': False,                'overrides': [                    {'method': 'email', 'minutes': 24 * 60},                    {'method': 'popup', 'minutes': 10}                ]            }        }                # 👉 CREATE EVENT NO CALENDAR        event = calendar.events().insert(calendarId='primary', body=event).execute()                logger.info(f"✅ Evento criado no Calendar: {event['id']} - {title}")        return event# ============================================# 🔔 NOTIFICAÇÃO PUSH (WebSocket para Frontend)# ============================================# 👉 PUSH: Enviar notificação push quando criar oportunidade, fechar contrato, etcclass PushNotificationService:    """Serviço de notificação push via WebSocket"""        def __init__(self, ws_manager: aiojobs.Scheduler):        self.ws_manager = ws_manager        async def send_push_notification(        self,         tenant_id: str,         notification_type: str,        title: str,        message: str,        data: dict = None    ):        """        Enviar notificação push via WebSocket        👉 PUSH: ws.send_json({type, title, message, data})        """        notification = {            "type": notification_type,            "title": title,            "message": message,            "data": data,            "timestamp": datetime.now().isoformat()        }                # 👉 ENVIAR PARA TODOS WS do tenant        await self.ws_manager.broadcast(            f"/ws/notifications/{tenant_id}",            notification        )                logger.info(f"✅ Push notification: {title} -> {tenant_id}")